SELECT 'retained_escape_route_products',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text) FROM software_discovery.escape_route_products t WHERE product_id IN ('db62ef76-724f-412f-9b63-d5b000d80ddc')),'[]'::jsonb)=(SELECT coalesce(jsonb_agg(j ORDER BY j::text),'[]'::jsonb) FROM (SELECT to_jsonb(jsonb_populate_record(NULL::software_discovery.escape_route_products,r)) j FROM jsonb_array_elements($verify$[]$verify$::jsonb) r) x)
UNION ALL
SELECT 'published_slug_sets_preserved',coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.products WHERE status='published'),'[]'::jsonb)=$verify$["2do","affine","anytype","appflowy","gimp","healthy-minds-program","joplin","krita","medito","obsidian","omnifocus","paint-net","pdf-xchange-editor","pdf24-creator","pdfgear","simplenote","smiling-mind","things"]$verify$::jsonb AND coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved),'[]'::jsonb)=$verify$["meditation-apps-without-a-subscription","notion-alternatives-without-ai","offline-notion-alternatives","pdf-editors-without-a-subscription","photoshop-alternatives-without-a-subscription","productivity-apps-you-can-buy-once","simple-notion-alternatives","todoist-alternatives-with-a-one-time-purchase"]$verify$::jsonb
UNION ALL
SELECT 'draft_lifecycle_and_public_boundary',(SELECT count(*)=3 AND bool_and(status='draft') FROM software_discovery.products WHERE slug IN ('hemingway-free-web','grazie-free-browser','real-write-passive-checker')) AND EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug='grammarly-alternatives-without-a-subscription' AND status='draft' AND NOT editorially_approved) AND software_discovery.product_discovery_page('hemingway-free-web') IS NULL AND software_discovery.product_discovery_page('grazie-free-browser') IS NULL AND software_discovery.product_discovery_page('real-write-passive-checker') IS NULL
UNION ALL
SELECT 'no_privacy_or_extra_claims',NOT EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug='privacy-friendly-grammarly-alternatives') AND NOT EXISTS(SELECT 1 FROM software_discovery.product_problems WHERE product_id IN (SELECT id FROM software_discovery.products WHERE slug IN ('hemingway-free-web','grazie-free-browser','real-write-passive-checker'))) AND NOT EXISTS(SELECT 1 FROM software_discovery.product_audiences WHERE product_id IN (SELECT id FROM software_discovery.products WHERE slug IN ('hemingway-free-web','grazie-free-browser','real-write-passive-checker')))
UNION ALL
SELECT 'anon_private_evidence_boundary',has_function_privilege('anon','software_discovery.product_discovery_page(text)','EXECUTE') AND NOT has_table_privilege('anon','software_discovery.claim_evidence','SELECT');
